def transform(grid):
    """Copy the rare colored pattern onto every matching all-zero footprint."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    candidates = [color for color in counts if color not in (0, background)]
    if not candidates:
        return [row[:] for row in grid]
    marker = min(candidates, key=lambda color: counts[color])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    min_r = min(r for r, _ in points)
    min_c = min(c for _, c in points)
    shape = [(r - min_r, c - min_c) for r, c in points]
    max_r = max(r for r, _ in shape)
    max_c = max(c for _, c in shape)
    motif = set(shape)
    out = [row[:] for row in grid]
    for top in range(h - max_r):
        for left in range(w - max_c):
            fits = all(
                grid[top + dr][left + dc] == (0 if (dr, dc) in motif else background)
                for dr in range(max_r + 1)
                for dc in range(max_c + 1)
            )
            if fits:
                for dr, dc in shape:
                    out[top + dr][left + dc] = marker
    return out


def main():
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))


if __name__ == "__main__":
    main()
